const PIECES = [...ORANGE.map((o) => o.id), ...BROWN.map((b) => b.id)];

export default function HandwrittenLogo({ onDone, className = "" }) {
  const uid = useId().replace(/[^a-zA-Z0-9]/g, "");
  const doneRef = useRef(onDone);
  doneRef.current = onDone;

  // Tell the parent when the writing (plus the hold) has finished
  useEffect(() => {
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    const ms = reduce ? 500 : TOTAL_MS / WRITE_SPEED + HOLD_MS;
    const id = setTimeout(() => doneRef.current?.(), ms);
    return () => clearTimeout(id);
  }, []);

  return (
    <svg
      viewBox="0 60 1180 910"
      className={className}
      role="img"
      aria-label="Ronak By Ali"
      xmlns="http://www.w3.org/2000/svg"
    >
      <style>{`
        .hl-pen { animation: hl-write both cubic-bezier(0.55, 0.05, 0.4, 1); }
        @keyframes hl-write { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
        .hl-ink { fill: var(--logo-ink, #4b210a); }
        .dark .hl-ink, [data-theme="dark"] .hl-ink { fill: var(--logo-ink, #f3e0cf); }
        @media (prefers-reduced-motion: reduce) {
          .hl-pen { animation: none; stroke-dashoffset: 0; }
        }
      `}</style>

      <defs>
        {PIECES.map((id) => (
          <mask key={id} id={`${uid}-${id}`} maskUnits="userSpaceOnUse" x="0" y="0" width="1180" height="1024">
            {STROKES.filter((s) => s.c === id).map((s, i) => (
              <path
                key={i}
                className="hl-pen"
                d={s.d}
                fill="none"
                stroke="#fff"
                strokeWidth={s.w}
                strokeLinecap="round"
                strokeLinejoin="round"
                pathLength="1"
                strokeDasharray="1 2"
                strokeDashoffset="1"
                style={{
                  animationDelay: `${s.from / WRITE_SPEED}ms`,
                  animationDuration: `${(s.to - s.from) / WRITE_SPEED}ms`,
                }}
              />
            ))}
          </mask>
        ))}
      </defs>

      {ORANGE.map((o) => (
        <g key={o.id} mask={`url(#${uid}-${o.id})`}>
          <image href={o.src} x={o.x} y={o.y} width={o.w} height={o.h} />
        </g>
      ))}
      {BROWN.map((b) => (
        <g key={b.id} mask={`url(#${uid}-${b.id})`}>
          <path className="hl-ink" d={b.d} fillRule="evenodd" />
        </g>
      ))}
    </svg>
  );
}
